#include <iostream>
#include <vector>
#include <queue>
#include <cstring>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 20;
const int MAXV = 2 * MAXN * MAXN;

char m1[MAXN][MAXN], m2[MAXN][MAXN];
int inf_time[MAXN][MAXN];
int n, t;

int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};

void bfs(int x, int y) {
    for (int a = 0; a < n; ++a)
        for (int b = 0; b < n; ++b)
            inf_time[a][b] = INF;
    inf_time[x][y] = 0;
    queue<pair<int, int>> fila;
    fila.push({x, y});
    while (!fila.empty()) {
        int cx = fila.front().first, cy = fila.front().second;
        fila.pop();
        for (int a = 0; a < 4; ++a) {
            int nx = cx + dx[a], ny = cy + dy[a];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if ('0' <= m1[nx][ny] && m1[nx][ny] <= '9' && inf_time[nx][ny] == INF) {
                inf_time[nx][ny] = inf_time[cx][cy] + 1;
                fila.push({nx, ny});
            }
        }
    }
}

vector<int> adj[MAXV];
int cap[MAXV][MAXV];

void add_edge(int u, int v, int c) {
    adj[u].push_back(v);
    adj[v].push_back(u);
    cap[u][v] = c;
    cap[v][u] = 0;
}

int tempo[MAXN][MAXN];
bool visited[MAXV];
int dist[MAXV];

bool bfs_level(int s, int t) {
    memset(dist, -1, sizeof(dist));
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    while (!q.empty() && dist[t] == -1) {
        int v = q.front(); q.pop();
        for (auto &nxt : adj[v]) {
            if (!cap[v][nxt] || dist[nxt] != -1) continue;
            dist[nxt] = dist[v] + 1;
            q.push(nxt);
        }
    }
    return dist[t] != -1;
}

void bfs2(int px, int py) {
    memset(tempo, INF, sizeof(tempo));
    tempo[px][py] = 0;
    if ('1' <= m2[px][py] && m2[px][py] <= '9')
        add_edge(n * px + py, n * n + n * px + py, INF);
    queue<pair<int, int>> q;
    q.push({px, py});
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int a = 0; a < 4; ++a) {
            int nx = x + dx[a], ny = y + dy[a];
            if (nx >= n || ny >= n || nx < 0 || ny < 0) continue;
            if (tempo[nx][ny] != INF) continue;
            if (!('0' <= m1[nx][ny] && m1[nx][ny] <= '9')) continue;
            if (tempo[x][y] + 1 <= min(inf_time[nx][ny] - 1, t)) {
                tempo[nx][ny] = tempo[x][y] + 1;
                q.push({nx, ny});
            }
            if (tempo[x][y] + 1 <= min(inf_time[nx][ny], t) && '1' <= m2[nx][ny] && m2[nx][ny] <= '9')
                add_edge(n * px + py, n * n + n * nx + ny, INF);
        }
    }
}

int dinic_dfs(int v, int t, int flow) {
    if (v == t) return flow;
    visited[v] = true;
    for (auto &nxt : adj[v]) {
        if (!cap[v][nxt] || visited[nxt] || dist[nxt] != dist[v] + 1) continue;
        int got = dinic_dfs(nxt, t, min(flow, cap[v][nxt]));
        if (got) {
            cap[v][nxt] -= got;
            cap[nxt][v] += got;
            return got;
        }
    }
    return 0;
}

int max_flow(int s, int t) {
    int total = 0, flow;
    while (bfs_level(s, t)) {
        memset(visited, 0, sizeof(visited));
        while ((flow = dinic_dfs(s, t, INF)) > 0) {
            total += flow;
            memset(visited, 0, sizeof(visited));
        }
    }
    return total;
}

int main() {
    cin >> n >> t;
    int sx, sy;
    int s_node = MAXV - 2, t_node = MAXV - 1;
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> m1[a][b];
            if (m1[a][b] == 'Z') {
                sx = a; sy = b;
            } else if ('1' <= m1[a][b] && m1[a][b] <= '9') {
                add_edge(s_node, a * n + b, m1[a][b] - '0');
            }
        }
    }
    bfs(sx, sy);
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            cin >> m2[a][b];
            if ('1' <= m2[a][b] && m2[a][b] <= '9') {
                add_edge(n * n + a * n + b, t_node, m2[a][b] - '0');
            }
        }
    }
    for (int a = 0; a < n; ++a) {
        for (int b = 0; b < n; ++b) {
            if ('1' <= m1[a][b] && m1[a][b] <= '9') {
                bfs2(a, b);
            }
        }
    }
    cout << max_flow(s_node, t_node) << "\n";
    return 0;
}
